// ═══ newFixedThreadPool — most common in production ═══
ExecutorService fixed = Executors.newFixedThreadPool(10);
// 10 worker threads, LinkedBlockingQueue (UNBOUNDED! ← danger: OOM if tasks pile up)
// Tasks queued when all 10 busy. Good for: known workload, CPU-bound tasks.
fixed.submit(() -> settleTrade("TRD-001"));
fixed.shutdown();  // stop accepting, finish running tasks

// ═══ newCachedThreadPool — elastic, for short-lived tasks ═══
ExecutorService cached = Executors.newCachedThreadPool();
// 0 threads initially. Creates new thread if none idle. Max: Integer.MAX_VALUE!
// Idle threads die after 60 seconds. SynchronousQueue (no buffering — direct handoff).
// DANGER: unbounded threads! 10K tasks → 10K threads → OOM!
// Good for: many short-lived tasks with low concurrent count.

// ═══ newSingleThreadExecutor — sequential, ordered ═══
ExecutorService single = Executors.newSingleThreadExecutor();
// 1 worker thread. LinkedBlockingQueue. Tasks execute ONE AT A TIME, in order.
// Good for: sequential processing, event logging, single-writer patterns.
// If the thread dies, a new one is created automatically.

// ═══ newScheduledThreadPool — delayed and periodic ═══
ScheduledExecutorService scheduled = Executors.newScheduledThreadPool(5);
scheduled.schedule(() -> generateReport(), 5, TimeUnit.SECONDS);  // delay 5s
scheduled.scheduleAtFixedRate(() -> checkHealth(), 0, 30, TimeUnit.SECONDS);  // every 30s
scheduled.scheduleWithFixedDelay(() -> cleanup(), 0, 1, TimeUnit.MINUTES);  // 1min AFTER previous ends

// ═══ CUSTOM ThreadPoolExecutor — full control (production recommended!) ═══
ThreadPoolExecutor custom = new ThreadPoolExecutor(
    10,                            // corePoolSize
    50,                            // maxPoolSize (scale up under load)
    60, TimeUnit.SECONDS,          // idle threads above core die after 60s
    new LinkedBlockingQueue<>(1000), // bounded queue! Back-pressure!
    new ThreadPoolExecutor.CallerRunsPolicy()  // rejection: caller executes!
);
// BEST for production: bounded queue + rejection policy + monitoring

// ═══ WHY NOT new Thread() in production? ═══
// 10K requests → new Thread() each → 10K threads → 10GB stack → OOM!
// No limit, no reuse, no monitoring, no graceful shutdown.
// Thread pool: 10 threads handle 10K requests → reuse → ~10MB stack → controlled.
