package com.bank.pool;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class ThreadPoolTest {

    // ═══ Fixed thread pool — bounded workers ═══
    @Test
    void fixedPool_reusesThreads() throws InterruptedException {
        ExecutorService pool = Executors.newFixedThreadPool(3);
        ConcurrentHashMap<String, Boolean> threadNames = new ConcurrentHashMap<>();
        CountDownLatch latch = new CountDownLatch(30);

        for (int i = 0; i < 30; i++) {
            pool.submit(() -> {
                threadNames.put(Thread.currentThread().getName(), true);
                latch.countDown();
            });
        }
        latch.await();
        pool.shutdown();

        // Only 3 unique thread names — reused for 30 tasks!
        assertThat(threadNames).hasSize(3);
    }

    // ═══ Single thread executor — sequential order ═══
    @Test
    void singleThread_sequential() throws InterruptedException {
        ExecutorService pool = Executors.newSingleThreadExecutor();
        StringBuilder order = new StringBuilder();
        CountDownLatch latch = new CountDownLatch(5);

        for (int i = 0; i < 5; i++) {
            final int num = i;
            pool.submit(() -> {
                order.append(num);
                latch.countDown();
            });
        }
        latch.await();
        pool.shutdown();

        assertThat(order.toString()).isEqualTo("01234");  // sequential!
    }

    // ═══ Scheduled pool — delayed and periodic ═══
    @Test
    void scheduledPool_delayedExecution() throws InterruptedException {
        ScheduledExecutorService scheduled = Executors.newScheduledThreadPool(2);
        AtomicBoolean executed = new AtomicBoolean(false);

        scheduled.schedule(() -> executed.set(true), 200, TimeUnit.MILLISECONDS);

        assertThat(executed.get()).isFalse();  // not yet!
        Thread.sleep(500);
        assertThat(executed.get()).isTrue();   // executed after delay!

        scheduled.shutdown();
    }

    // ═══ Custom pool — bounded queue + rejection policy ═══
    @Test
    void customPool_boundedQueueWithRejection() throws InterruptedException {
        AtomicInteger completed = new AtomicInteger(0);
        AtomicInteger rejected = new AtomicInteger(0);

        ThreadPoolExecutor pool = new ThreadPoolExecutor(
            2, 4, 60, TimeUnit.SECONDS,
            new LinkedBlockingQueue<>(5),
            (r, executor) -> rejected.incrementAndGet()  // custom rejection handler
        );

        // Submit 20 tasks — some will be rejected (queue full + max threads busy)
        for (int i = 0; i < 20; i++) {
            try {
                pool.submit(() -> {
                    try { Thread.sleep(100); } catch (InterruptedException e) { }
                    completed.incrementAndGet();
                });
            } catch (RejectedExecutionException e) {
                rejected.incrementAndGet();
            }
        }

        pool.shutdown();
        pool.awaitTermination(10, TimeUnit.SECONDS);

        System.out.println("Completed: " + completed.get() + ", Rejected: " + rejected.get());
        assertThat(completed.get() + rejected.get()).isGreaterThanOrEqualTo(20);
    }

    // ═══ Shutdown: graceful vs immediate ═══
    @Test
    void shutdown_gracefulVsImmediate() throws InterruptedException {
        ExecutorService pool = Executors.newFixedThreadPool(2);
        AtomicInteger completed = new AtomicInteger(0);

        for (int i = 0; i < 5; i++) {
            pool.submit(() -> {
                try { Thread.sleep(100); } catch (InterruptedException e) { return; }
                completed.incrementAndGet();
            });
        }

        pool.shutdown();  // graceful: no new tasks, finish running + queued
        // pool.shutdownNow();  // immediate: interrupt running, discard queued
        pool.awaitTermination(10, TimeUnit.SECONDS);

        assertThat(completed.get()).isEqualTo(5);  // all 5 finished!
    }
}
